/* ---------------- 2. origin ---------------- */
{
  const s = p.addSlide();
  titleSlide(s, "ORIGIN", "A framework carried across archetype",
    "The solver and the assembly are unchanged, while the governing physics differs.");

  s.addText([
    { text: "The framework originates in the Stagnone di Marsala digital twin, a coupled Delft3D FM and SWAN model of a shallow vegetated lagoon in western Sicily.", options: { breakLine: true, paraSpaceAfter: 10 } },
    { text: "A transfer to a second lagoon would remain within a single archetype and would test little. A transfer to a deep engineered harbour tests whether the pipeline is reusable or was fitted to one site.", options: { breakLine: true, paraSpaceAfter: 10 } },
    { text: "The stages that transfer constitute the reuse. Those that do not mark where the generality of the framework ends, and they are recorded as such.", options: {} },
  ], { x: M, y: 2.25, w: 5.7, h: 3.0, fontSize: 14.5, color: INK, fontFace: BODY,
       lineSpacing: 22, isTextBox: true, margin: 0 });

  const rows = [
    ["", "Stagnone", "Valletta"],
    ["Depth", "sub-metre", "12 to 20 m"],
    ["Bed", "seagrass canopy", "engineered, quay walls"],
    ["Boundary signal", "tide", "long wave, atmospheric"],
    ["Circulation driver", "wind", "the same long wave"],
  ];
  s.addTable(rows.map((r, i) => r.map((c, j) => ({
    text: c,
    options: {
      bold: i === 0 || j === 0,
      color: i === 0 ? WHITE : INK,
      fill: { color: i === 0 ? BLUE : (i % 2 ? WHITE : TINT) },
      fontSize: 12.5, fontFace: BODY, valign: "middle",
    },
  }))), { x: 6.85, y: 2.25, w: 5.86, colW: [1.86, 2.0, 2.0], rowH: 0.46,
          border: { type: "solid", color: "D6DEE3", pt: 0.5 } });

  note(s, "The transfer effort is logged stage by stage as transferred, re-parameterised or not applicable. That log constitutes the methodological result.");
  s.addNotes("The thesis contribution is framework reusability, and Valletta constitutes the harder test.");
}

/* ---------------- 3. data in hand ---------------- */
