/* ---------------- 4. the phenomenon ---------------- */
{
  const s = p.addSlide();
  titleSlide(s, "THE PHENOMENON", "The milgħuba as a meteotsunami",
    "An atmospherically generated long wave, known as rissaga in the Balearics and as marrobbio on the Sicilian shelf.");

  const stages = [
    ["Proudman resonance", "Energy transfers most efficiently when the atmospheric disturbance travels at the celerity of the long wave beneath it.",
     "The Malta Plateau, 99 to 190 m deep, would be resonant with disturbances travelling at 94 to 155 km h⁻¹."],
    ["Shoaling", "Green's law governs the amplification of the wave over the shoaling approach.",
     "From 150 m on the plateau into the harbours, a factor of 1.75 to 1.84."],
    ["Basin resonance", "The geometry of the basin amplifies the wave arriving at its mouth.",
     "First-order estimates place the fundamental modes at 14.5 to 18.4 minutes in the Grand Harbour and 10.4 to 12.8 in Marsamxett."],
  ];
  stages.forEach((st, i) => {
    const x = M + i * 4.12;
    s.addShape(p.ShapeType.roundRect, { x, y: 2.72, w: 3.85, h: 2.5,
      fill: { color: TINT }, rectRadius: 0.06 });
    badge(s, i + 1, x + 0.28, 2.42, i === 0 ? ORANGE : BLUE);
    s.addText(st[0], { x: x + 0.28, y: 3.05, w: 3.3, h: 0.36, fontSize: 15.5,
      bold: true, color: INK, fontFace: HEAD, isTextBox: true, margin: 0 });
    s.addText(st[1], { x: x + 0.28, y: 3.44, w: 3.3, h: 0.82, fontSize: 12,
      color: INK, fontFace: BODY, lineSpacing: 16, isTextBox: true, margin: 0 });
    s.addText(st[2], { x: x + 0.28, y: 4.32, w: 3.3, h: 0.8, fontSize: 11,
      color: TEAL, bold: true, fontFace: BODY, lineSpacing: 15, isTextBox: true, margin: 0 });
  });

  note(s, "At Ciutadella, Menorca, the reference site of the rissaga, the three stages compound to an order of magnitude. No equivalent decomposition has been published for Malta.");
  s.addNotes("The three-stage chain organises the study and determines the domain.");
}

/* ---------------- 5. natural periods ---------------- */
{
  const s = p.addSlide();
  titleSlide(s, "NATURAL PERIODS", "First-order estimates of the natural periods",
    "Quarter-wave periods, T = 4L∕√(gh), for the shelf and the inlets, and eigenmodes of the measured profile for the harbours, against the 0.2 to 2 cph band reported by Drago (2009).");

  const rows = [
    ["Element", "Basis", "Period", "Frequency", ""],
    ["Plateau to Sicily, quarter wave", "90 km, 150 m", "156 min", "0.38 cph", "within"],
    ["Plateau to Sicily, half wave", "90 km, 150 m", "78 min", "0.77 cph", "within"],
    ["Near plateau", "25 km, 120 m", "49 min", "1.24 cph", "within"],
    ["Grand Harbour", "measured profile", "14.5 to 18.4 min", "3.3 to 4.1 cph", "outside"],
    ["Marsamxett", "measured profile", "10.4 to 12.8 min", "4.7 to 5.8 cph", "outside"],
    ["A 1 km inlet", "1.0 km, 12 m", "6 min", "9.76 cph", "outside"],
  ];
  s.addTable(rows.map((r, i) => r.map((c, j) => {
    const head = i === 0;
    const inBand = c === "within";
    return { text: c, options: {
      bold: head || j === 0 || inBand,
      color: head ? WHITE : (inBand ? ORANGE : (c === "outside" ? MUTED : INK)),
      fill: { color: head ? BLUE : (i <= 3 ? "FDF0E9" : WHITE) },
      fontSize: 12, fontFace: BODY, valign: "middle",
      align: j === 0 ? "left" : (j === 4 ? "left" : "right"),
    } };
  })), { x: M, y: 2.5, w: 8.5, colW: [2.85, 1.5, 1.65, 1.55, 0.95], rowH: 0.375,
         border: { type: "solid", color: "E2E8EC", pt: 0.5 } });

  s.addShape(p.ShapeType.roundRect, { x: 9.45, y: 2.5, w: 3.26, h: 3.55,
    fill: { color: MID }, rectRadius: 0.06 });
  s.addText("Reading for the domain", { x: 9.75, y: 2.75, w: 2.7, h: 0.32, fontSize: 14,
    bold: true, color: ORANGE, fontFace: HEAD, isTextBox: true, margin: 0 });
  s.addText([
    { text: "On these estimates the plateau has natural periods within the band and the harbours above it, which suggests that the harbours respond to a shelf-scale oscillation.\n", options: { breakLine: true } },
    { text: "A domain confined to the harbours would then hold no resonator in the band.\n", options: { breakLine: true } },
    { text: "A domain extending over the plateau is therefore proposed.", options: { bold: true, color: WHITE } },
  ], { x: 9.75, y: 3.15, w: 2.7, h: 2.8, fontSize: 11.5, color: PALE,
       fontFace: BODY, lineSpacing: 15, valign: "top", isTextBox: true, margin: 0 });

  note(s, "The upper edge of the band, 2 cph, corresponds to 30 minutes, 1.6 times the upper estimate for the Grand Harbour and 2.3 times that for Marsamxett.");
  s.addNotes("The proposed domain follows from this table. The CMEMS boundary product is not expected to carry energy in the band. The harbour rows come from a one-dimensional eigenvalue calculation on the measured profile and are tested against the Senglea record on the following slide.");
}

/* ---------------- 6. estimated and observed modes ---------------- */
{
  const s = p.addSlide();
  titleSlide(s, "BASIN MODES", "Estimated and observed modes of the Grand Harbour",
    "A test of the harbour estimate of the preceding slide, on which the choice of domain rests, against the spectrum of the Senglea radar gauge inside the basin (JRC TAD device 555, 5 s sampling, nine months admitted).");

  s.addImage({ path: path.join(FIG, "senglea_spectrum.png"), x: M, y: 2.3, w: 6.3, h: 4.3 });

  table(s, [
    ["Observed period", "Frequency", "Peak ∕ background", "Relation to the estimate"],
    ["23.0 min", "2.61 cph", "23.8", "longer than estimated"],
    ["16.8 min", "3.57 cph", "10.1", "within 14.5 to 18.4 min"],
    ["10.0 min", "5.98 cph", "7.6", ""],
    ["6.9 min", "8.67 cph", "15.2", "near the inlet estimate"],
  ], { x: 7.2, y: 2.3, w: 5.51, colW: [1.3, 0.95, 1.26, 2.0], rowH: 0.34, fontSize: 11 },
  (j) => (j === 0 || j === 3 ? "left" : "right"));

  box(s, 7.2, 4.14, 5.51, 2.46, "Preliminary reading", [
    { text: "The observed peaks lie above the milgħuba band, in agreement with the estimate.", options: { bullet: true, breakLine: true, paraSpaceAfter: 5 } },
    { text: "The dominant peak, at 23 minutes, is longer than estimated. It may be the fundamental, underestimated by the calculation, or a mode of the approach shared by the two harbours.", options: { bullet: true, breakLine: true, paraSpaceAfter: 5 } },
    { text: "On the supplied coastline, removing the St Elmo breakwater changes the estimate by 0.1 minute.", options: { bullet: true } },
  ], true);

  note(s, "A single gauge does not separate the two readings of the 23-minute peak. The modal structure computed on the mesh, or a second gauge, would.");
  s.addNotes("The estimate comes from the long-wave eigenproblem of a channel of varying section, g d/dx(a dη/dx) + ω² b η = 0, solved on the cross-section a(x) and the surface width b(x) measured along the geodesic distance from the mouth, with the mouth correction of Rabinovich (2009, eq. 9.16). It is one-dimensional and first-order. Panels, from the upper left. The mean spectrum with its background, the milgħuba band shaded grey and the estimated basin band shaded blue. The ratio of the spectrum to the background. The largest oscillation of the admitted windows, 8 November 2021, with a range of 0.35 m. The amplitude ratio against the gauges outside the harbour. The peaks recur on practically every day of both windows, which points to the geometry rather than to the forcing. The section at the entrance is within 6 per cent of the median section of the basin, which suggests that the inertia of the mode is distributed along the harbour. Whether the Ricasoli arm narrows the real opening is unresolved, and a narrower opening would alter that reading.");
}

/* ---------------- 7. events against the record ---------------- */
{
  const s = p.addSlide();
  titleSlide(s, "OBSERVATION", "Reported events against the public record",
    "The public copy of the Senglea record covers 43 per cent of the span from June 2021 to December 2024, and transmission ceased on 13 December 2024.");

  table(s, [
    ["Date", "Type", "Reported effects", "Senglea, public copy"],
    ["25 Oct 2018", "seismic tsunami", "excursions of some 25 cm at Portomaso", "before installation"],
    ["18 Jun 2019", "milgħuba", "sea bed exposed and quay overtopped in St Paul's Bay", "before installation"],
    ["30 Jun 2022", "milgħuba", "flooding at Marsaskala, St Julian's and Qawra", "no data, record resumes on 1 July"],
    ["1 Jul 2023", "milgħuba", "flooding at Marsaskala and Xemxija", "displaced level, not usable"],
    ["13 Jun 2024", "meteotsunami", "flooding of the main square of Msida", "displaced level, not usable"],
  ], { x: M, y: 2.4, w: 12.09, colW: [1.5, 1.8, 4.9, 3.89], rowH: 0.38 }, () => "left");

  box(s, M, 4.92, 5.95, 1.62, "State of the record",
    "Two windows are provisionally admitted to the analysis, 24 June to 31 December 2021 and 1 December 2022 to 31 March 2023, on monthly coverage and stability of the level. From April 2023 the level appears displaced by some 2 m and the gauge transmits by day only.", false);
  box(s, 6.76, 4.92, 5.95, 1.62, "Consequence for the study",
    "None of the three events since installation is resolved in the public copy, and Portomaso returns no data from the IOC facility on those dates. The archive of the group, sea level and one-minute pressure, would therefore be the record against which the response surface is tested.", true);

  s.addNotes("Sources. University of Malta Newspoint for 2018 and 2019, Newsbook for 2022, MaltaToday for 2023 and 2024, the last citing the Oceanography Malta Research Group. Upward radar echoes from vessels, rain and spray are removed by the lower envelope of the 5 s samples, and episodes of reference offset of 1.3 to 2.1 m are removed before the spectrum is computed. The choice of windows is to be confirmed within the group. The displaced level is compatible with the radar ranging to a vessel or pontoon beneath it, which is a conjecture.");
}

